USE weather_system;
CREATE TABLE IF NOT EXISTS device_alert (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, type VARCHAR(50), level VARCHAR(20), message VARCHAR(500), status VARCHAR(20) DEFAULT 'open', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, acknowledged_by VARCHAR(50), acknowledged_at DATETIME, FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS maintain_plan (id BIGINT PRIMARY KEY AUTO_INCREMENT, device_id BIGINT NOT NULL, title VARCHAR(200), cycle_days INT, next_date DATE, owner VARCHAR(50), status VARCHAR(20) DEFAULT 'pending', remark VARCHAR(500), create_time DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_id) REFERENCES device(id) ON DELETE CASCADE);
INSERT INTO maintain_plan(device_id,title,cycle_days,next_date,owner,status,remark) SELECT 1,'温度传感器月度保养',30,DATE_ADD(CURDATE(),INTERVAL 12 DAY),'张工','pending','检查探头、接线和防护罩' WHERE EXISTS (SELECT 1 FROM device WHERE id=1) AND NOT EXISTS (SELECT 1 FROM maintain_plan);
